/** ARM f2 (follow-up 4, exploit F2): money events the Runner may hold, from its deck list less the public cards (the grip and the stack as one: their union is the deck list less what is public, 10.2.2a, 10.2.3a); each event's credits over a click for a credit (Overclock's and Trick Shot's over the run's own click; Sell Out needs an installed resource; Wildcat Strike is the Corp's choice, Aircheck locks the pool: 0). `max`: the largest the Runner may hold (none with an empty grip); `odds`: the expected best one held, a grip of g drawn from the unseen cards (hypergeometric). */
const GRIP_MONEY: Record<string, number> = { '30030': 3, '30020': 2, '34001': 2, '30029': 4, '34087': 3, '36011': 2 };
function gripMoney(s: GameState): { max: number; odds: number } {
  const unseen = [...s.runner.grip, ...s.runner.stack];
  const g = s.runner.grip.length;
  const n = unseen.length;
  const byGain = new Map<number, number>();
  for (const c of unseen) {
    const m = GRIP_MONEY[c.cardCode];
    if (m && !(c.cardCode === '36011' && !s.runner.rig.resources.length)) byGain.set(m, (byGain.get(m) ?? 0) + 1);
  }
  if (!g || !byGain.size) return { max: 0, odds: 0 };
  const gains = [...byGain.keys()].sort((a, b) => b - a);
  // The chance no card of a set of k unseen cards is in the grip: C(n - k, g) / C(n, g)
  const none = (k: number) => {
    let p = 1;
    for (let i = 0; i < g; i++) p *= Math.max(0, n - k - i) / (n - i);
    return p;
  };
  let odds = 0;
  let k = 0;
  let prev = 1;
  for (const m of gains) {
    k += byGain.get(m)!;
    const p = none(k);
    odds += m * (prev - p);
    prev = p;
  }
  return { max: gains[0], odds };
}

